// A floor plan GENERATED by Gemini, as checked geometry. The model writes the
// plan document PLAN_GENERATE_PROMPT asks for (rooms as rectangles, doors and
// windows by room + side); code does everything else:
//   coercePlanGenerate → ops → PlanEngine.applyGenerated on a blank document
//   → sanitizePlanDoc → the accessibility and plan checks shown in review.
// Code builds every wall, reuses shared walls and assigns every id, so a
// reply can never name a wall it could not know. The drawing rides BESIDE
// the board's surface plan (`drawings`), never inside it (planDocs.ts).
//
// What leaves this device: her words and the fixed instructions. Nothing
// from the canvas, no device, no drawing.
import type { SentInfo } from './aiTurn';
import { extractJson, hasCompleteJson } from '../ai/cloudJson';
import { coercePlanGenerate, MAX_GENERATE_ROOMS, PLAN_GENERATE_CONSTRAINT, PLAN_GENERATE_PROMPT } from '../plan/ai';
import { PlanEngine } from '../plan/engine';
import type { PlanDoc } from '../plan/doc';
import { sanitizePlanDoc } from './planDocs';
import { planRooms } from './planEdit';
import { checkPlanAccessibility } from '../plan/accessibility';
import { answerPlanQuestion } from '../cad/planQA';

export const PLAN_GENERATE_FAIL = "I couldn't draw that plan. Nothing was generated.";
export const PLAN_GENERATE_ROUTE_LINE = 'Gemini · cloud — drawing the floor plan as checked geometry';
export const PLAN_GENERATE_SENT = 'your words about the plan. No board, no device, no drawing.';
export { PLAN_GENERATE_CONSTRAINT };

const isObj = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v);
const fin = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);

/** Her words, inside the prompt: one line, no quotes. */
const said = (s: string): string => s.replace(/[\r\n"“”\\]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 200);

export function buildPlanGeneratePrompt(utterance: string): SentInfo {
  const prompt = `${PLAN_GENERATE_PROMPT}\nShe said: "${said(utterance)}"`;
  return { engine: 'gemini', prompt, sent: PLAN_GENERATE_SENT, routeLine: PLAN_GENERATE_ROUTE_LINE, sim: false };
}

export type PlanFromReply =
  | { ok: true; doc: Record<string, unknown>; rooms: { name: string; w: number; h: number }[]; findings: string[] }
  | { ok: false; error: string };

interface Rect { x: number; y: number; w: number; h: number }
/** Interior overlap (a shared edge is not one), as in expandPlanDocument. */
const overlaps = (a: Rect, b: Rect): boolean => a.x + a.w - 1 > b.x && b.x + b.w - 1 > a.x && a.y + a.h - 1 > b.y && b.y + b.h - 1 > a.y;

/** A reply → a checked drawing. Strict where the shared expansion is lenient:
 *  a room with a size that is not a finite positive number, or two rooms on
 *  top of each other, refuse the whole plan (what she reviews is all of what
 *  was written, never a plan with rooms quietly left out). Rooms past
 *  MAX_GENERATE_ROOMS are not drawn. */
export function planFromReply(text: string): PlanFromReply {
  const bad = (error: string): PlanFromReply => ({ ok: false, error });
  if (!hasCompleteJson(text)) return bad('the reply holds no complete JSON');
  const raw = extractJson(text);
  if (!isObj(raw)) return bad('the reply is not a plan document');
  if (typeof raw.clarify === 'string' && raw.clarify.trim()) return bad(`Gemini asked: ${raw.clarify.trim().slice(0, 120)}`);
  if (!Array.isArray(raw.rooms) || !raw.rooms.length) return bad('the plan has no rooms');
  const kept = raw.rooms.slice(0, MAX_GENERATE_ROOMS);
  const toMm = raw.unit === 'm' ? 1000 : raw.unit === 'cm' ? 10 : 1;
  const rects: Rect[] = [];
  for (const [i, r] of kept.entries()) {
    if (!isObj(r) || !fin(r.x) || !fin(r.y) || !fin(r.w) || !fin(r.h) || r.w <= 0 || r.h <= 0) return bad(`room ${i + 1} has no real size`);
    const rect = { x: r.x * toMm, y: r.y * toMm, w: r.w * toMm, h: r.h * toMm };
    if (rects.some((o) => overlaps(o, rect))) return bad(`room ${i + 1} overlaps another room`);
    rects.push(rect);
  }
  const g = coercePlanGenerate({ ...raw, rooms: kept });
  if (!g || !('ops' in g)) return bad('the plan did not pass its check');
  const engine = new PlanEngine();
  const applied = engine.applyGenerated(g.ops);
  if (!applied.ok) return bad(`the plan could not be drawn: ${applied.error}`);
  const doc = sanitizePlanDoc(engine.getState());
  if (!doc) return bad('the drawing failed its check');
  const pd = doc as unknown as PlanDoc;
  const boxes = planRooms(pd);
  if (boxes.length !== kept.length) return bad('a room could not be drawn');
  const rooms = boxes.map((b) => ({ name: b.name, w: Math.round(b.w / 100) / 10, h: Math.round(b.h / 100) / 10 }));
  const findings = [
    ...checkPlanAccessibility(pd).map((i) => i.message),
    ...[answerPlanQuestion(pd, 'how many walls?')?.text].filter((t): t is string => !!t),
  ];
  return { ok: true, doc, rooms, findings };
}
